import net.minecraft.client.Minecraft;
import net.minecraft.client.multiplayer.ClientLevel;
import net.minecraft.client.player.LocalPlayer;
import net.minecraft.world.Difficulty;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.level.ServerExplosion;
import net.minecraft.world.phys.Vec3;

public final class ExplosionPredict {
   private ExplosionPredict() {}

   /**
    * Raw pre-armour explosion damage vanilla would deal to the local player.
    * `power` is the ServerExplosion `radius` field (respawn anchor = 5.0F); reach is power*2.
    * Includes Player.hurtServer difficulty scaling (all explosion types are scaling:"always"),
    * excludes armour / Protection / resistance / absorption.
    */
   public static float rawSelfDamage(final float power, final Vec3 center) {
      Minecraft mc = Minecraft.getInstance();
      LocalPlayer player = mc.player;
      ClientLevel level = mc.level;
      if (player == null || level == null || power < 1.0E-5F) {
         return 0.0F;                                   // ServerExplosion.hurtEntities guard
      }
      float doubleRadius = power * 2.0F;
      double dist = Math.sqrt(player.distanceToSqr(center)) / doubleRadius;
      if (dist > 1.0) {
         return 0.0F;                                   // hurtEntities() range cutoff
      }
      // exposure: 45 raycasts for a standing player, ClipContext.Block.COLLIDER / Fluid.NONE
      float exposure = ServerExplosion.getSeenPercent(center, player);
      double pow = (1.0 - dist) * exposure;
      float raw = (float)((pow * pow + pow) / 2.0 * 7.0 * doubleRadius + 1.0);

      Difficulty difficulty = level.getDifficulty();
      if (difficulty == Difficulty.PEACEFUL) {
         return 0.0F;
      } else if (difficulty == Difficulty.EASY) {
         return Math.min(raw / 2.0F + 1.0F, raw);
      } else if (difficulty == Difficulty.HARD) {
         return raw * 3.0F / 2.0F;
      }
      return raw;                                       // NORMAL
   }

   /**
    * The knockback ServerExplosion would push. In practice the server sends the authoritative
    * vector in ClientboundExplodePacket.playerKnockback(); this is the local estimate.
    * Assumes a plain ExplosionDamageCalculator (multiplier 1.0F) -- true for respawn anchors.
    */
   public static Vec3 predictKnockback(final float power, final Vec3 center) {
      Minecraft mc = Minecraft.getInstance();
      LocalPlayer player = mc.player;
      if (player == null || power < 1.0E-5F) {
         return Vec3.ZERO;
      }
      float doubleRadius = power * 2.0F;
      double dist = Math.sqrt(player.distanceToSqr(center)) / doubleRadius;
      if (dist > 1.0) {
         return Vec3.ZERO;
      }
      float knockbackMultiplier = player.getAbilities().flying ? 0.0F : 1.0F;
      float exposure = ServerExplosion.getSeenPercent(center, player);
      double resist = player.getAttributeValue(Attributes.EXPLOSION_KNOCKBACK_RESISTANCE);
      double magnitude = (1.0 - dist) * exposure * knockbackMultiplier * (1.0 - resist);
      // direction is from the EYE position, not the feet position used for `dist`
      return player.getEyePosition().subtract(center).normalize().scale(magnitude);
   }

   /** Respawn anchor: power 5.0F, centre = Vec3.atCenterOf(pos) (block centre, +0.5 on each axis). */
   public static float rawAnchorSelfDamage(final Vec3 anchorBlockCenter) {
      return rawSelfDamage(5.0F, anchorBlockCenter);
   }
}
